// Some portions generated by Claude Code

// Once a result lives in browser storage, a new batch of rows is taken into memory at once and written behind: the
// query stream reads its next record while the worker writes the previous one. Waiting for every write let the page and
// the worker take turns, and left the result far behind the rows the server sent.

const test = require('node:test');
const assert = require('node:assert/strict');
const { MemoryWorker, loadApi } = require('./query-load-more-harness.js');

function rows(from, to) {
    return Array.from({ length: to - from }, (_, index) => [{ kind: 'literal', value: String(from + index) }]);
}

function values(batch) {
    return [...batch].map((row) => row[0].value);
}

async function settle(rounds = 20) {
    for (let index = 0; index < rounds; index++) await new Promise((resolve) => setImmediate(resolve));
}

async function moved(store, rounds = 100) {
    for (let index = 0; index < rounds && store.inMemory; index++) await new Promise((resolve) => setImmediate(resolve));
}

/** Rejects when the promise does not settle within ms: the store must not wait for browser storage. */
function within(promise, ms = 200) {
    let timer;
    return Promise.race([promise, new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error('did not settle within ' + ms + ' ms')), ms);
    })]).finally(() => clearTimeout(timer));
}

/** A worker that holds every request while holding is set, and answers them in order on release (as IndexedDB does). */
class HoldingWorker extends MemoryWorker {
    constructor() {
        super();
        this.holding = false;
        this.held = [];
        this.posted = [];
    }
    postMessage(message) {
        this.posted.push(message);
        if (this.holding || this.held.length) {
            this.held.push(message);
            return;
        }
        super.postMessage(message);
    }
    release() {
        this.holding = false;
        this.held.splice(0).forEach((message) => super.postMessage(message));
    }
}

/** A worker whose appends fail once failing is set, as browser storage over its quota. */
class QuotaWorker extends MemoryWorker {
    postMessage(message) {
        if (this.failing && message.op === 'append') {
            this.messages.push(message);
            queueMicrotask(() => {
                for (const callback of this.listeners.get('message') || []) {
                    callback({ data: { requestId: message.requestId, ok: false,
                        error: 'QuotaExceededError: The quota has been exceeded.' } });
                }
            });
            return;
        }
        super.postMessage(message);
    }
}

async function storedResult(api, worker, options = {}) {
    const store = await api.createRowStore(Object.assign({ workerFactory: () => worker, spillRowLimit: 0 }, options));
    return store;
}

test('a stored result takes rows without waiting for browser storage, keeps them readable and writes them in order',
    async () => {
        const { api } = loadApi();
        const worker = new HoldingWorker();
        const store = await storedResult(api, worker);
        assert.equal(await store.append(rows(0, 2)), 2);
        await moved(store);
        assert.equal(store.inMemory, false);

        worker.holding = true;
        assert.equal(await within(store.append(rows(2, 4))), 4, 'the append does not wait for the write');
        assert.equal(await within(store.append(rows(4, 6))), 6);
        assert.equal(await within(store.count()), 6, 'the count includes the rows waiting to be written');
        assert.deepEqual(values(await within(store.read(3, 3))), ['3', '4', '5'],
            'rows waiting to be written are read from memory');
        await settle();
        const appends = worker.posted.filter((message) => message.op === 'append');
        assert.equal(appends.length, 2, 'the move, then one write at a time');
        assert.equal(appends[1].rowCount, 2);

        const spanning = store.read(0, 6);
        worker.release();
        assert.deepEqual(values(await spanning), ['0', '1', '2', '3', '4', '5'], 'a read across written and waiting rows');
        await settle();
        assert.deepEqual(values(worker.rows), ['0', '1', '2', '3', '4', '5']);
        assert.equal(await store.count(), 6);
        await store.dispose();
    });

test('rows that wait to be written are written together, in batches of at most 5,000 rows', async () => {
    const { api } = loadApi();
    const worker = new HoldingWorker();
    const store = await storedResult(api, worker);
    await store.append(rows(0, 1));
    await moved(store);
    worker.holding = true;
    await store.append(rows(1, 2));
    for (let from = 2; from < 8002; from += 1000) {
        await store.append(rows(from, from + 1000));
    }
    worker.release();
    await settle(60);
    const writes = worker.posted.filter((message) => message.op === 'append').slice(1).map((message) => message.rowCount);
    assert.equal(writes[0], 1, 'the first write starts at once');
    assert.ok(writes.slice(1).every((count) => count <= 5000), JSON.stringify(writes));
    assert.ok(writes.length <= 4, 'the rows that came meanwhile are written together: ' + JSON.stringify(writes));
    assert.equal(worker.rows.length, 8002);
    assert.deepEqual(values(worker.rows.slice(7998)), ['7998', '7999', '8000', '8001']);
    await store.dispose();
});

test('an append waits for room only once the rows waiting to be written fill memory', async () => {
    const { api } = loadApi();
    const worker = new HoldingWorker();
    const store = await storedResult(api, worker, { memoryRowLimit: 4 });
    await store.append(rows(0, 1));
    await moved(store);
    worker.holding = true;
    assert.equal(await within(store.append(rows(1, 4))), 4);
    let settled = false;
    const waiting = store.append(rows(4, 6)).then((count) => { settled = true; return count; });
    await settle();
    assert.equal(settled, false, 'five rows waiting would pass the memory limit of four');
    worker.release();
    assert.equal(await waiting, 6);
    await settle();
    assert.deepEqual(values(worker.rows), ['0', '1', '2', '3', '4', '5']);
    await store.dispose();
});

test('when memory is full and browser storage stops answering, the append fails and says so', async () => {
    const { api } = loadApi();
    const worker = new HoldingWorker();
    const store = await storedResult(api, worker, { memoryRowLimit: 3, storageTimeout: 30 });
    await store.append(rows(0, 1));
    await moved(store);
    worker.holding = true;
    assert.equal(await store.append(rows(1, 3)), 3);
    const error = await store.append(rows(3, 5)).then(() => null, (failure) => failure);
    assert.ok(error, 'the append fails');
    assert.match(error.message, /Browser storage did not answer/);
    assert.equal(error.code, 'storage');
    assert.equal(await store.count(), 3, 'a batch that does not fit is not kept in part');
    assert.deepEqual(values(await within(store.read(1, 2))), ['1', '2']);
    await store.dispose();
});

test('after a failed write later appends are refused, and the rows already taken stay readable', async () => {
    const { api } = loadApi();
    const worker = new QuotaWorker();
    const store = await storedResult(api, worker);
    await store.append(rows(0, 2));
    await moved(store);
    worker.failing = true;
    assert.equal(await store.append(rows(2, 4)), 4, 'the rows are taken before the write fails');
    await settle();
    const error = await store.append(rows(4, 5)).then(() => null, (failure) => failure);
    assert.ok(error, 'the next append is refused');
    assert.match(error.message, /quota/i);
    assert.equal(error.code, 'storage', 'the page can offer to reset browser storage');
    assert.equal(await store.count(), 4);
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1', '2', '3']);
    await store.dispose();
});

test('a stored result truncates correctly while rows wait to be written', async () => {
    const { api } = loadApi();
    const worker = new HoldingWorker();
    const store = await storedResult(api, worker);
    await store.append(rows(0, 3));
    await moved(store);
    worker.holding = true;
    await store.append(rows(3, 6));
    await store.append(rows(6, 8));
    const cut = store.truncate(7);
    worker.release();
    assert.equal(await cut, 7);
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1', '2', '3', '4', '5', '6']);
    await settle();
    assert.deepEqual(values(worker.rows), ['0', '1', '2', '3', '4', '5', '6'], 'a cut row is never written');
    assert.equal(await store.truncate(2), 2, 'a truncate below the written rows cuts browser storage');
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1']);
    assert.equal(await store.append(rows(10, 12)), 4);
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1', '10', '11']);
    await settle();
    assert.deepEqual(values(worker.rows), ['0', '1', '10', '11']);
    await assert.rejects(store.truncate(5), /exceed/i);
    await store.dispose();
});

test('disposing a stored result while rows wait to be written ends cleanly', async () => {
    const { api } = loadApi();
    const worker = new HoldingWorker();
    const store = await storedResult(api, worker);
    await store.append(rows(0, 1));
    await moved(store);
    worker.holding = true;
    await store.append(rows(1, 3));
    await store.append(rows(3, 4));
    const disposed = store.dispose();
    worker.release();
    await disposed;
    await settle();
    assert.equal(worker.terminated, true);
    await assert.rejects(store.append(rows(4, 5)), /disposed/i);
});

test('memory holds at most 1,000,000 rows and 256 MB of estimated row size', () => {
    const { api } = loadApi();
    assert.equal(api.MEMORY_ROW_STORE_LIMIT, 1000000);
    assert.equal(api.MEMORY_BYTE_LIMIT, 256 * 1024 * 1024);
});
